from functools import wraps
import sys
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils.paths import default_value_if_there_is_no_robot_context


logger = custom_logger('ConfigurationProvider')
Disabled = False


class VARIABLES(object):
    ONLINE_EGATE = 'ONLINE_EGATE'
    CONFIG_DISABLED = 'CONFIG_DISABLED'
    CONFIGURATION = 'CONFIGURATION'
    SIMULATOR = 'SIM'
    KEEP_ALIVE = "KEEP_ALIVE"


def get(variable):
    return '${%s}' % variable


@default_value_if_there_is_no_robot_context(Disabled)
def is_enabled(variable):
    from robot.libraries.BuiltIn import BuiltIn
    variable_value = BuiltIn().get_variable_value(get(variable))
    return Disabled if variable_value is None else str(variable_value).lower() == 'true'


@default_value_if_there_is_no_robot_context(None)
def is_set_to_value(variable):
    from robot.libraries.BuiltIn import BuiltIn
    variable_value = BuiltIn().get_variable_value(get(variable))
    return variable_value


@default_value_if_there_is_no_robot_context(None)
def library_robot_instance(library_name):
    from robot.libraries.BuiltIn import BuiltIn
    library_instance = BuiltIn().get_library_instance(library_name)
    return library_instance


def disabled_on(*flags):
    def disabled_when_flags_are_enabled(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if not all(is_enabled(flag) for flag in flags):
                return func(*args, **kwargs)
            logger.warn('{} DISABLED'.format(func))
        return wrapper
    return disabled_when_flags_are_enabled


def disabled_on_any(*flags):
    def disabled_when_any_flag_is_enabled(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if not any(is_enabled(flag) for flag in flags):
                return func(*args, **kwargs)
            logger.warn('{} DISABLED'.format(func))
        return wrapper
    return disabled_when_any_flag_is_enabled


def is_online_egate_enabled():
    return is_enabled(VARIABLES.ONLINE_EGATE)


def is_keep_alive_enabled():
    return is_enabled(VARIABLES.KEEP_ALIVE)


def dryrun_is_set():
    return '--dryrun' in sys.argv or configuration_value() == "dryrun"


def configuration_value():
    return is_set_to_value(VARIABLES.CONFIGURATION)


def chosen_simulator():
    return is_set_to_value(VARIABLES.SIMULATOR)


disabled_on_online_egate = disabled_on(VARIABLES.ONLINE_EGATE)
